def add(self, sku, qty=1):
    """加购。SKU 不存在会由 catalog 抛 KeyError；数量必须为正；加购后该 SKU 累计数量不得超库存。"""
    if qty <= 0:
        raise ValueError("数量必须为正")
    item = catalog.get_item(sku)      # 校验 SKU 存在
    qty = int(qty)
    in_cart = sum(q for s, q in self._lines if s == sku)
    if in_cart + qty > item["stock"]:
        raise ValueError(
            f"{sku} 库存不足：购物车已有 {in_cart} 件，本次加购 {qty} 件，库存仅 {item['stock']} 件"
        )
    self._lines.append((sku, qty))
    return self
